command -v python3>/dev/null||exit 127;python3 -c 'import sys,json as j,os,math;f="state.json";o=j.load(open(f))if os.path.exists(f)and os.path.getsize(f)else{};T=lambda x:x>1 and(x==2 or x%2>0 and all(x%d for d in range(3,math.isqrt(x)+1,2)));n=int(sys.argv[1])if len(sys.argv)>1 else o.get("n",0)+1;assert n>0;m=1;c=0;exec("while c<n:\n m+=1\n if T(m):c+=1");X={"model":"PRIME_INDEX_HOLOGRAM_TM","n":n,"p":m,"pi_p":c,"prime":T(m),"ordinal_exact":c==n,"log_state":["log",m],"atom":["forall","a,b in N+","ab=p","a=1 or b=1"],"godel":["mul",["pow",2,m+1],["pow",3,n+1]],"decode":["v2(G)-1","v3(G)-1"],"prime_formula":"p_n=min{N>=2:pi(N)=n}","pi_formula":"pi(N)=sum_{k=2}^N 1_P(k)","indicator":"1_P(k)=1 iff no d in [2,isqrt(k)] divides k","zeta_link":"-zeta_prime(s)/zeta(s)=sum Lambda(k)k^-s","boundary":{"R_zeta_1":1,"meaning":"lim_(s->1+)(s-1)zeta(s)=1"},"claims":{"exact_integer":True,"elementary_scalar_closed_form":False,"RH_proved":False}};b=j.dumps(X,sort_keys=True,separators=(",",":")).encode();Y={**X,"hologram":{"coeff":list(b),"reconstruct":j.loads(b.decode())==X},"exact":{"float":False,"sha":False}};open(f,"w").write(j.dumps(Y,separators=(",",":")));print(j.dumps(Y,separators=(",",":")))' "$@"